parameters.jsCode:
const items = $input.all();

function cleanText(value) {
  if (value === null || value === undefined) return '';

  return String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function numberOrNull(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

const output = [];

for (const item of items) {
  const article = item.json || {};

  // ---------------------------------------
  // MARKETaux ENTITIES
  // ---------------------------------------

  const entities = Array.isArray(article.entities)
    ? article.entities
    : [];

  // Keep entities that have a stock/entity symbol
  const validEntities = entities
    .filter(e => e && e.symbol)
    .map(e => ({
      symbol: String(e.symbol).toUpperCase(),
      name: cleanText(e.name),
      type: cleanText(e.type),
      industry: cleanText(e.industry),
      country: cleanText(e.country),
      exchange: cleanText(e.exchange),
      exchange_long: cleanText(e.exchange_long),

      match_score: numberOrNull(e.match_score),
      sentiment_score: numberOrNull(e.sentiment_score),

      highlights: Array.isArray(e.highlights)
        ? e.highlights.map(h => ({
            text: cleanText(h.highlight),
            sentiment: numberOrNull(h.sentiment),
            highlighted_in: cleanText(h.highlighted_in)
          }))
        : []
    }));

  // ---------------------------------------
  // SORT ENTITIES BY MATCH SCORE
  // ---------------------------------------

  const sortedEntities = [...validEntities].sort(
    (a, b) => (b.match_score || 0) - (a.match_score || 0)
  );

  // Most relevant entity
  const primaryEntity = sortedEntities[0] || null;

  // ---------------------------------------
  // UNIQUE SYMBOLS
  // ---------------------------------------

  const symbols = [
    ...new Set(
      validEntities.map(e => e.symbol)
    )
  ];

  // ---------------------------------------
  // AVERAGE SENTIMENT
  // ---------------------------------------

  const sentimentValues = validEntities
    .map(e => e.sentiment_score)
    .filter(v => v !== null);

  const averageSentiment = sentimentValues.length
    ? sentimentValues.reduce(
        (sum, value) => sum + value,
        0
      ) / sentimentValues.length
    : null;

  // ---------------------------------------
  // COLLECT HIGHLIGHTS
  // ---------------------------------------

  const highlights = [];

  for (const entity of validEntities) {
    for (const h of entity.highlights) {
      if (h.text) {
        highlights.push({
          symbol: entity.symbol,
          text: h.text,
          sentiment: h.sentiment,
          highlighted_in: h.highlighted_in
        });
      }
    }
  }

  // ---------------------------------------
  // BUILD AI INPUT TEXT
  // ---------------------------------------

  const newsText = [
    `Title: ${cleanText(article.title)}`,

    `Description: ${cleanText(article.description)}`,

    `Snippet: ${cleanText(article.snippet)}`,

    `Source: ${cleanText(article.source)}`,

    `Published: ${cleanText(article.published_at)}`,

    `Symbols: ${symbols.join(', ')}`,

    primaryEntity
      ? `Primary Company: ${primaryEntity.name} (${primaryEntity.symbol})`
      : '',

    primaryEntity?.industry
      ? `Industry: ${primaryEntity.industry}`
      : '',

    primaryEntity?.sentiment_score !== null &&
    primaryEntity?.sentiment_score !== undefined
      ? `Marketaux Sentiment: ${primaryEntity.sentiment_score}`
      : '',

    highlights.length
      ? `Relevant Highlights: ${highlights
          .map(h => `${h.symbol}: ${h.text}`)
          .join(' | ')}`
      : ''
  ]
    .filter(Boolean)
    .join('\n');

  // ---------------------------------------
  // OUTPUT
  // ---------------------------------------

  output.push({
    json: {
      news_id: article.uuid || '',

      title: cleanText(article.title),

      description: cleanText(article.description),

      snippet: cleanText(article.snippet),

      url: article.url || '',

      image_url: article.image_url || '',

      language: article.language || '',

      source: cleanText(article.source),

      published_at: article.published_at || '',

      // All identified symbols
      symbols,

      // Primary entity
      primary_symbol: primaryEntity?.symbol || '',

      primary_company: primaryEntity?.name || '',

      primary_industry: primaryEntity?.industry || '',

      primary_country: primaryEntity?.country || '',

      primary_exchange: primaryEntity?.exchange || '',

      primary_exchange_long:
        primaryEntity?.exchange_long || '',

      primary_match_score:
        primaryEntity?.match_score ?? null,

      primary_sentiment:
        primaryEntity?.sentiment_score ?? null,

      average_sentiment:
        averageSentiment,

      // Complete entities
      entities: validEntities,

      // Highlights
      highlights,

      // Compact text for AI
      news_text: newsText
    }
  });
}

return output;
